WITH metrics AS (SELECT *, FIRST_VALUE(channel) IGNORE NULLS OVER w_hist AS first_known_channel, NTILE(3) OVER w_part AS discount_pct_bucket, LAG(discount_pct, 1) OVER w_part AS prev_discount_pct FROM promotions WINDOW w_hist AS (PARTITION BY channel ORDER BY starts_on ASC, id ASC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW), w_part AS (PARTITION BY promo_code ORDER BY discount_pct ASC, id ASC)) SELECT CASE WHEN discount_pct >= 0.31 THEN 'LARGE' ELSE 'SMALL' END AS discount_pct_tier, SUM(CASE WHEN channel = 'mobile' THEN discount_pct_bucket ELSE 0 END) AS mobile_discount_pct_bucket, COUNT(DISTINCT channel) AS distinct_channels, AVG(prev_discount_pct) AS avg_prev_discount_pct, SUM(discount_pct) AS total_discount_pct, APPROX_PERCENTILE(discount_pct, 0.9) AS discount_pct_p90, APPROX_PERCENTILE(discount_pct_bucket, 0.9) AS discount_pct_bucket_p90 FROM metrics GROUP BY 1 ORDER BY distinct_channels ASC NULLS FIRST
